import java.io.*;
import java.util.*;

public class P1575D {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        String line = reader.readLine();
        char[] s = line.toCharArray();
        int total = 0;

        if (s.length == 1) {
            if (s[0] == '0' || s[0] == '_' || s[0] == 'X') {
                total = 1;
            }
        } else {
            int n = s.length;
            if (!(s[n - 1] == 'X' && s[n - 2] == 'X')) {
                if (canPlace(s, n - 1, '5') && canPlace(s, n - 2, '2')) {
                    char[] temp = Arrays.copyOf(s, n);
                    assign(temp, n - 1, '5');
                    assign(temp, n - 2, '2');
                    total += countWays(temp);
                }
                if (canPlace(s, n - 1, '0') && canPlace(s, n - 2, '5')) {
                    char[] temp = Arrays.copyOf(s, n);
                    assign(temp, n - 1, '0');
                    assign(temp, n - 2, '5');
                    total += countWays(temp);
                }
                if (canPlace(s, n - 1, '5') && canPlace(s, n - 2, '7')) {
                    char[] temp = Arrays.copyOf(s, n);
                    assign(temp, n - 1, '5');
                    assign(temp, n - 2, '7');
                    total += countWays(temp);
                }
            }
            if (s[n - 1] == 'X' && s[n - 2] == 'X') {
                char[] temp = Arrays.copyOf(s, n);
                assign(temp, n - 1, '0');
                total += countWays(temp);
            } else if (canPlace(s, n - 1, '0') && canPlace(s, n - 2, '0')) {
                char[] temp = Arrays.copyOf(s, n);
                assign(temp, n - 1, '0');
                assign(temp, n - 2, '0');
                total += countWays(temp);
            }
        }
        out.println(total);
        out.flush();
    }

    private static boolean canPlace(char[] s, int index, char d) {
        return s[index] == 'X' || s[index] == '_' || s[index] == d;
    }

    private static void assign(char[] s, int index, char d) {
        if (s[index] == 'X') {
            fill(s, d);
        } else {
            s[index] = d;
        }
    }

    private static void fill(char[] s, char d) {
        for (int i = 0; i < s.length; i++) {
            if (s[i] == 'X') {
                s[i] = d;
            }
        }
    }

    private static int countWays(char[] s) {
        int ways = 1;
        if (s[0] == '0') {
            return 0;
        }
        if (s[0] == '_') {
            ways *= 9;
        } else if (s[0] == 'X') {
            ways *= 9;
            fill(s, '1');
        }
        for (int i = 1; i < s.length; i++) {
            if (s[i] == '_') {
                ways *= 10;
            } else if (s[i] == 'X') {
                ways *= 10;
                fill(s, '1');
            }
        }
        return ways;
    }
}
